export const FX={parts:[],flashes:0,flashCol:'#00f0ff',banner:null,redPulse:0,setBanner(txt,sub=''){this.banner={txt,sub,t:0}},emit(x,y,col,n=6){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=0.5+Math.random()*2;this.parts.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:30+Math.random()*30,max:60,col,r:1+Math.random()*2})}},update(){for(let i=this.parts.length-1;i>=0;i--){const p=this.parts[i];p.x+=p.vx;p.y+=p.vy;p.vx*=0.95;p.vy*=0.95;p.life--;if(p.life<=0)this.parts.splice(i,1)}if(this.banner)this.banner.t+=0.016;if(this.flashes>0)this.flashes-=0.016;if(this.redPulse>0)this.redPulse-=0.016},draw(ctx){for(const p of this.parts){const a=Math.max(0,p.life/p.max);ctx.globalAlpha=a;ctx.fillStyle=p.col;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}}